fn bitwise_and(x1: &Vec<u8>, x2: &Vec<u8>) -> Vec<u8> {
    // Pre-allocate a result vector of the same length
    let len = x1.len();
    let mut result = Vec::with_capacity(len);

    // For each index i, compute the bitwise AND of x1[i] and x2[i]
    for i in 0..len {
        result.push(x1[i] & x2[i]);
    }

    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic() {
        let a = vec![0b0000_1100, 0b1111_0000, 0b1010_1010];
        let b = vec![0b0000_1010, 0b1100_1100, 0b1111_0000];
        let c = bitwise_and(&a, &b);
        assert_eq!(c, vec![0b0000_1000, 0b1100_0000, 0b1010_0000]);

        // Commutativity: a & b == b & a
        assert_eq!(bitwise_and(&a, &b), bitwise_and(&b, &a));

        // AND with zero yields zero
        let zero = vec![0; 3];
        assert_eq!(bitwise_and(&a, &zero), zero);
        assert_eq!(bitwise_and(&zero, &a), zero);

        // AND with itself yields the original
        assert_eq!(bitwise_and(&a, &a), a);
        assert_eq!(bitwise_and(&b, &b), b);

        // Each result element is <= each of the corresponding inputs
        for i in 0..a.len() {
            let r = c[i];
            assert!(r <= a[i]);
            assert!(r <= b[i]);
        }
    }
}